import{_ as t,o as a,c as i,a3 as r}from"./chunks/framework.CchDE9cb.js";const h=JSON.parse(`{"title":"CapacityLens threat model","description":"The security objectives, assets, actors, abuse cases and accepted risks that shape CapacityLens's design.","frontmatter":{"title":"CapacityLens threat model","description":"The security objectives, assets, actors, abuse cases and accepted risks that shape CapacityLens's design."},"headers":[],"relativePath":"security/threat-model.md","filePath":"security/threat-model.md","lastUpdated":1785253498000}`),o={name:"security/threat-model.md"};function s(n,e,d,c,l,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="capacitylens-threat-model" tabindex="-1">CapacityLens threat model <a class="header-anchor" href="#capacitylens-threat-model" aria-label="Permalink to &quot;CapacityLens threat model&quot;">​</a></h1><p>Version: 2026-07-14. Review this model after changes to authentication, tenancy, imports, offline storage, deployment topology or external services.</p><h2 id="security-objectives" tabindex="-1">Security objectives <a class="header-anchor" href="#security-objectives" aria-label="Permalink to &quot;Security objectives&quot;">​</a></h2><ol><li>A user can read or change only accounts, operations, records and protected fields allowed by their current server-side membership and role.</li><li>Passwords, session tokens, reset/invite tokens, MFA seeds/recovery codes and provider secrets are not disclosed or stored in recoverable form where a safer representation is possible.</li><li>Tenant writes remain valid, atomic and attributable; corrupted relational state prevents startup.</li><li>Browser-delivered code cannot silently turn an authenticated browser into a cross-site write primitive, and sensitive API responses are not cached.</li><li>Operators can contain a compromised identity, restore authoritative data and investigate typed security/audit events without relying on the compromised host alone.</li></ol><p>CapacityLens is not a safety-critical, payments, classified-data, real-time media or anonymous public-upload system. Availability is important but confidentiality and tenant integrity take priority over keeping a misconfigured production process running.</p><h2 id="assets-and-trust-boundaries" tabindex="-1">Assets and trust boundaries <a class="header-anchor" href="#assets-and-trust-boundaries" aria-label="Permalink to &quot;Assets and trust boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Asset</th><th>Primary protection</th><th>Boundary</th></tr></thead><tbody><tr><td>Account schedule and private client/project names</td><td>Server membership, action/field authorization, SQLite constraints</td><td>Browser/API and tenant boundary</td></tr><tr><td>Identity, password and MFA state</td><td>Better Auth, versioned scrypt, encrypted recovery material, fixed sessions</td><td>Auth/API and database boundary</td></tr><tr><td>Session, reset and invite bearer values</td><td>HttpOnly cookies or one-time values; hashes where supported; expiry/revocation</td><td>Browser/API and operator delivery boundary</td></tr><tr><td>Offline snapshot</td><td>Opt-in, role-filtered, AES-256-GCM, seven-day expiry, viewer-only</td><td>Browser-origin/device boundary</td></tr><tr><td>Database, WAL, audit and snapshots</td><td><code>0600</code> files, <code>0700</code> backup directory, optional encrypted-volume attestation</td><td>Process/host boundary</td></tr><tr><td>Audit and security events</td><td>Data-minimised JSON, local restrictive file plus optional separately forwarded stream</td><td>Process/log-collector boundary</td></tr><tr><td>Build and release inputs</td><td>Lockfile, pinned images/actions, dependency review, SBOM, scans and provenance</td><td>Contributor/CI/registry boundary</td></tr></tbody></table><p>The packaged production flow is browser → public TLS proxy → unprivileged web container → verified per-install internal TLS → unprivileged HTTPS API container → local SQLite/backup volumes. A bare-metal deployment may instead use HTTP only over a same-host loopback hop. In both shapes the API must not be publicly reachable and the proxy must overwrite rather than append forwarding headers.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li>Viewer, editor, admin and owner, all potentially malicious within their legitimate account.</li><li>An authenticated user attempting cross-account or higher-role access.</li><li>An unauthenticated internet attacker, automated credential attacker or cross-site origin.</li><li>A compromised browser profile or device.</li><li>A malicious/compromised identity provider, dependency, build input or container base.</li><li>A self-hosting operator who makes an accidental or unsafe configuration choice.</li><li>A host-level attacker. Host compromise is not fully preventable in-process; encrypted storage, secret management, isolation and off-host logs/backups limit consequences.</li></ul><h2 id="abuse-cases-and-controls" tabindex="-1">Abuse cases and controls <a class="header-anchor" href="#abuse-cases-and-controls" aria-label="Permalink to &quot;Abuse cases and controls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Threat</th><th>Principal controls</th><th>Verification</th></tr></thead><tbody><tr><td>BOLA/IDOR or cross-tenant mutation</td><td>Membership fetched server-side for each operation; every scoped entity has <code>accountId</code>; row-addressed generic writes make absent and foreign ids response-indistinguishable; row/reference validation fails closed when a project-bound allocation cannot resolve its project in the same account; cross-account tests</td><td><code>app.authz</code>, <code>app.members</code>, tenant-store, route and shared mutation tests</td></tr><tr><td>Function/field privilege escalation</td><td>Central action matrix; protected-name projection/preservation; owner-only import; fresh session for privileged actions</td><td>access, privacy and route tests</td></tr><tr><td>Credential stuffing/password cracking</td><td>Positive global/API throttling; five-attempt MFA lock; 15–128 Unicode code points; HIBP range check; scrypt <code>N=2^17,r=8,p=1</code>; no default password</td><td>password/auth/rate-limit tests</td></tr><tr><td>Password-only account takeover</td><td>Opt-in required TOTP wall before tenant data; otherwise long passwords, HIBP by default, scrypt, throttling and bounded/revocable sessions; one-time MFA recovery codes</td><td>real auth integration and UI tests</td></tr><tr><td>Session theft/fixation</td><td>Secure HttpOnly SameSite <code>__Host-</code> cookies; new token on auth; fixed 12-hour and 30-minute idle limits; revocation/reset invalidation; session inventory</td><td>auth and member revocation tests</td></tr><tr><td>CSRF and cross-origin data use</td><td>Unsafe-method Origin/Sec-Fetch-Site rejection; exact configured or trusted-proxy-derived same origin; SameSite cookie; safe HTTP methods</td><td>CSRF/CORS and packaged-proxy tests</td></tr><tr><td>Injection/XSS/mass assignment</td><td>React text rendering; no untrusted HTML; parameterized SQLite; explicit table/column codecs; sanitisation and structural limits; CSP</td><td>server/shared/CSP tests</td></tr><tr><td>Malicious or oversized import</td><td>JSON-only, 5 MiB/200,000-record caps; schema migration/sanitisation; account remap; reference validation; atomic owner-only transaction</td><td>import and mutation tests</td></tr><tr><td>Offline cache disclosure/tampering</td><td>Role-filtered input; non-extractable device key; AES-GCM with random IV/AAD; tamper/expiry deletion; viewer-only</td><td>offline cache tests</td></tr><tr><td>Database corruption/partial write</td><td>Startup foreign-key check; WAL; transactions; optimistic concurrency; atomic imports/backups</td><td>migration, transaction and restore-drill tests</td></tr><tr><td>Log erasure/injection or invisible attack</td><td>Structured serialization, no values/credentials, restrictive modes, health degradation latch and optional separate JSON forwarding</td><td>audit/log/production-guard tests</td></tr><tr><td>SSRF/provider substitution</td><td>Operator-only exact issuer/discovery; endpoints validated before redirect or secret use; HTTPS outside loopback; no credentials/redirects; 10-second and 1 MiB provider-response bounds; signed ID-token issuer/audience/timestamp verification; JWKS rotation and user-info subject binding</td><td>strict OIDC crypto/exchange tests and pinned Dex browser conformance</td></tr><tr><td>Resource exhaustion</td><td>512 accepted-socket ceiling; per-IP application/CSP rate limit with constant-work health exempt for reliable liveness; 2-active/16-queued scrypt and 8-active/32-queued HIBP work; import/CSP caps; request timeouts</td><td>resource-queue/rate-limit/health/import/CSP tests</td></tr><tr><td>Supply-chain compromise</td><td>Exact lockfile, pinned action/base-image commits/digests, Dependabot, CodeQL, Gitleaks, dependency review, SBOM, Trivy, ZAP and tagged provenance</td><td>local gates and public/manual workflows</td></tr></tbody></table><h2 id="residual-and-accepted-risks" tabindex="-1">Residual and accepted risks <a class="header-anchor" href="#residual-and-accepted-risks" aria-label="Permalink to &quot;Residual and accepted risks&quot;">​</a></h2><ul><li>Strict OIDC is first-class. Better Auth owns state, PKCE and cookies; the account adapter owns issuer-pinned endpoint selection, the bounded no-redirect code exchange, ID-token signature/audience/timestamp checks, JWKS rotation and user-info subject equality. Named social providers remain experimental and every IdP still needs staging interoperability, MFA-policy and logout/session-lifetime testing.</li><li>IdP disablement does not revoke already-issued local sessions. The accepted maximum is the remaining twelve-hour absolute lifetime or thirty minutes inactivity; local revocation is an incident-response requirement and back-channel logout must be reconsidered before hosted GA.</li><li>Required TOTP is optional. Password-only deployments do not meet ASVS 5.0 Level 2 requirement V6.3.3; when enabled, TOTP meets L2 but remains phishable and insufficient for L3.</li><li>Existing legacy Better Auth scrypt hashes use the former weaker profile until the user changes or resets the password. They are verify-only; new material never uses that format.</li><li>The application has no IP/device-risk engine, anomalous-login user notification, global administrator “revoke everyone” control or HSM/full-memory encryption.</li><li>Public TLS, encrypted host volumes, secret-manager/HSM use, clock synchronization, log retention and off-host collection are deployment controls. Internal service TLS is application-packaged for Compose and optional for a same-host bare-metal hop; startup warnings cannot verify external controls.</li><li>An unlocked or compromised application origin can invoke its non-extractable offline key. Device encryption, patching and profile access control remain necessary.</li><li>A single-process SQLite service can still be denied service by sufficient network or tenant-valid load. Edge rate limiting, connection limits and resource monitoring remain operator controls.</li></ul>',14)])])}const m=t(o,[["render",s]]);export{h as __pageData,m as default};
